const name = "Party jollof"
const price = 3500
const spicy = true
const soldOut = false

function DishOfTheDay() {
  return (
    <article className="card">
      <h3>{name}</h3>
      <p>₦{price.toLocaleString()}</p>
      {spicy && <span className="hot">🌶️ Spicy</span>}
      <p className="status" style={{ fontWeight: "bold" }}>{soldOut ? "Sold out today" : "Order now"}</p>
    </article>
  )
}

ReactDOM.createRoot(document.getElementById("root")).render(<DishOfTheDay />)
